/**
 * 物品集合（图鉴分组）。
 *
 * 数据来源：FishShopConfig/js/search.js 的
 * itemCollections / classCollections / friendCollections，逐条校验后
 * 全部 ID 均存在于 data/items.json（1..6195 无缺号）。
 *
 * 约定：
 * - 本文件是前端静态配置，不写入 data/（data/ 由 tools/gen-data.mjs 生成，禁止手改）。
 * - 每组集合内部保留原始书写顺序，仅去重；展示排序由页面决定。
 * - ID 区间（idRanges）已作为 range 分组纳入，便于按 ID 段浏览。
 * - 别名集合（itemAliases）不单独建集合：与分类集合重复。
 */

import type { Item } from '@/types'

export type CollectionGroup = 'category' | 'class' | 'friend' | 'range'

export interface ItemCollection {
  id: string
  name: string
  group: CollectionGroup
  ids: number[]
}

/** 分组展示顺序（Popover 折叠区）：ID 范围紧跟在「制作界面」之后。 */
export const COLLECTION_GROUPS: CollectionGroup[] = ['range', 'category', 'class', 'friend']

/** 生成闭区间 [start, end] 的 ID 列表（用于「ID 区间」集合）。 */
function rangeIds(start: number, end: number): number[] {
  const out: number[] = []
  for (let id = start; id <= end; id++) out.push(id)
  return out
}

